                    Track Order
                  </Link>
                </motion.div>
                <motion.div whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}>
                  <Link 
                    to="/employee" 
                    className="premium-button text-sm px-6 py-2.5"
                  >
                    Employee Portal
                  </Link>
                </motion.div>
              </motion.div>
            </div>
          </div>
        </motion.nav>

        {/* Main Content */}
        <div className="pt-16 min-h-screen flex items-center justify-center px-4">
